export interface ModalDialogOptions {
  readonly title: string;
  readonly content: string;
  readonly closeButtonText?: string;
  readonly onOpen?: () => void;
  readonly onClose?: () => void;
}

export interface ModalDialogState {
  isOpen: boolean;
  title: string;
  content: string;
}

export class ModalDialog {
  private options: ModalDialogOptions;
  private state: ModalDialogState;
  private containerElement: HTMLElement | null = null;
  private backdropElement: HTMLElement | null = null;
  private closeButtonElement: HTMLElement | null = null;

  constructor(options: ModalDialogOptions) {
    this.options = options;
    this.state = {
      isOpen: false,
      title: options.title,
      content: options.content,
    };
  }

  public open(): void {
    if (this.state.isOpen) {
      return;
    }
    this.state.isOpen = true;
    this.render();
    if (this.options.onOpen) {
      this.options.onOpen();
    }
  }

  public close(): void {
    if (!this.state.isOpen) {
      return;
    }
    this.state.isOpen = false;
    this.destroy();
    if (this.options.onClose) {
      this.options.onClose();
    }
  }

  public isOpen(): boolean {
    return this.state.isOpen;
  }

  public setTitle(title: string): void {
    this.state.title = title;
    if (this.containerElement) {
      const heading = this.containerElement.querySelector(".modal-title");
      if (heading) {
        heading.textContent = title;
      }
    }
  }

  public setContent(content: string): void {
    this.state.content = content;
    if (this.containerElement) {
      const body = this.containerElement.querySelector(".modal-body");
      if (body) {
        body.textContent = content;
      }
    }
  }

  public render(): HTMLElement {
    if (typeof document === "undefined") {
      return this.renderToStringStub();
    }

    this.backdropElement = document.createElement("div");
    this.backdropElement.className = "modal-backdrop";

    this.containerElement = document.createElement("div");
    this.containerElement.className = "modal-dialog";

    const header = document.createElement("div");
    header.className = "modal-header";

    const titleElem = document.createElement("h2");
    titleElem.className = "modal-title";
    titleElem.textContent = this.state.title;

    this.closeButtonElement = document.createElement("button");
    this.closeButtonElement.className = "modal-close-btn";
    this.closeButtonElement.textContent = this.options.closeButtonText ?? "×";
    this.closeButtonElement.addEventListener("click", () => this.close());

    header.appendChild(titleElem);
    header.appendChild(this.closeButtonElement);

    const body = document.createElement("div");
    body.className = "modal-body";
    body.textContent = this.state.content;

    const footer = document.createElement("div");
    footer.className = "modal-footer";

    const confirmBtn = document.createElement("button");
    confirmBtn.className = "modal-confirm-btn";
    confirmBtn.textContent = "Confirm";
    confirmBtn.addEventListener("click", () => this.close());

    footer.appendChild(confirmBtn);

    this.containerElement.appendChild(header);
    this.containerElement.appendChild(body);
    this.containerElement.appendChild(footer);

    this.backdropElement.appendChild(this.containerElement);
    document.body.appendChild(this.backdropElement);

    return this.containerElement;
  }

  public renderToString(): string {
    const closeText = this.options.closeButtonText ?? "×";
    return `
<div class="modal-backdrop">
  <div class="modal-dialog">
    <div class="modal-header">
      <h2 class="modal-title">${this.state.title}</h2>
      <button class="modal-close-btn">${closeText}</button>
    </div>
    <div class="modal-body">${this.state.content}</div>
    <div class="modal-footer">
      <button class="modal-confirm-btn">Confirm</button>
    </div>
  </div>
</div>`.trim();
  }

  private renderToStringStub(): HTMLElement {
    const elem = {
      className: "modal-dialog",
      innerHTML: this.renderToString(),
    } as unknown as HTMLElement;
    return elem;
  }

  public destroy(): void {
    if (this.backdropElement && this.backdropElement.parentNode) {
      this.backdropElement.parentNode.removeChild(this.backdropElement);
    }
    this.backdropElement = null;
    this.containerElement = null;
    this.closeButtonElement = null;
  }
}

