export interface FormFieldSchema {
  readonly name: string;
  readonly label: string;
  readonly type: "text" | "email" | "password" | "checkbox" | "select";
  readonly required?: boolean;
  readonly options?: readonly { readonly label: string; readonly value: string }[];
  readonly defaultValue?: string | boolean;
}

export interface FormValues {
  [key: string]: string | boolean | undefined;
}

export interface FormErrors {
  [key: string]: string;
}

export interface AccessibleFormOptions {
  readonly fields: readonly FormFieldSchema[];
  readonly onSubmit: (values: FormValues) => void;
  readonly submitButtonText?: string;
}

export class AccessibleForm {
  private options: AccessibleFormOptions;
  private values: FormValues = {};
  private errors: FormErrors = {};
  private formElement: HTMLElement | null = null;

  constructor(options: AccessibleFormOptions) {
    this.options = options;
    for (const field of options.fields) {
      this.values[field.name] = field.defaultValue ?? (field.type === "checkbox" ? false : "");
    }
  }

  public setFieldValue(name: string, value: string | boolean): void {
    this.values[name] = value;
    if (this.errors[name]) {
      delete this.errors[name];
    }
  }

  public getFieldValue(name: string): string | boolean | undefined {
    return this.values[name];
  }

  public getErrors(): FormErrors {
    return { ...this.errors };
  }

  public validate(): boolean {
    const newErrors: FormErrors = {};
    for (const field of this.options.fields) {
      const val = this.values[field.name];
      if (field.required) {
        if (field.type === "checkbox" && val !== true) {
          newErrors[field.name] = `${field.label} is required`;
        } else if (typeof val !== "string" || val.trim().length === 0) {
          newErrors[field.name] = `${field.label} is required`;
        }
      }
      if (field.type === "email" && typeof val === "string" && val.length > 0) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(val)) {
          newErrors[field.name] = "Please enter a valid email address";
        }
      }
    }
    this.errors = newErrors;
    return Object.keys(newErrors).length === 0;
  }

  public handleSubmit(event?: Event): void {
    if (event) {
      event.preventDefault();
    }
    const isValid = this.validate();
    if (isValid) {
      this.options.onSubmit({ ...this.values });
    } else {
      this.updateErrorDisplay();
    }
  }

  private updateErrorDisplay(): void {
    if (!this.formElement) {
      return;
    }
    for (const field of this.options.fields) {
      const errorMsg = this.errors[field.name];
      const errorContainer = this.formElement.querySelector(`.error-${field.name}`);
      if (errorContainer) {
        errorContainer.textContent = errorMsg ?? "";
      }
    }
  }

  public render(): HTMLElement {
    if (typeof document === "undefined") {
      return this.renderToStringStub();
    }

    const form = document.createElement("form");
    form.className = "form-component";
    form.addEventListener("submit", (e) => this.handleSubmit(e));

    for (const field of this.options.fields) {
      const group = document.createElement("div");
      group.className = "form-group";

      const label = document.createElement("label");
      label.textContent = field.label;
      group.appendChild(label);

      let inputElem: HTMLElement;
      if (field.type === "select") {
        const select = document.createElement("select");
        select.name = field.name;
        for (const opt of field.options ?? []) {
          const optionElem = document.createElement("option");
          optionElem.value = opt.value;
          optionElem.textContent = opt.label;
          select.appendChild(optionElem);
        }
        select.addEventListener("change", () => {
          this.setFieldValue(field.name, select.value);
        });
        inputElem = select;
      } else {
        const input = document.createElement("input");
        input.type = field.type;
        input.name = field.name;
        if (field.type === "checkbox") {
          input.checked = Boolean(this.values[field.name]);
          input.addEventListener("change", () => {
            this.setFieldValue(field.name, input.checked);
          });
        } else {
          input.value = String(this.values[field.name] ?? "");
          input.addEventListener("input", () => {
            this.setFieldValue(field.name, input.value);
          });
        }
        inputElem = input;
      }
      group.appendChild(inputElem);

      const errorSpan = document.createElement("span");
      errorSpan.className = `form-error error-${field.name}`;
      errorSpan.textContent = this.errors[field.name] ?? "";
      group.appendChild(errorSpan);

      form.appendChild(group);
    }

    const submitBtn = document.createElement("button");
    submitBtn.type = "submit";
    submitBtn.className = "form-submit-btn";
    submitBtn.textContent = this.options.submitButtonText ?? "Submit";
    form.appendChild(submitBtn);

    this.formElement = form;
    return form;
  }

  public renderToString(): string {
    const fieldHtml = this.options.fields
      .map((field) => {
        const errorText = this.errors[field.name] ?? "";
        return `
    <div class="form-group">
      <label>${field.label}</label>
      <input type="${field.type}" name="${field.name}" value="${String(this.values[field.name] ?? "")}" />
      <span class="form-error error-${field.name}">${errorText}</span>
    </div>`;
      })
      .join("\n");

    const submitText = this.options.submitButtonText ?? "Submit";
    return `
<form class="form-component">
${fieldHtml}
  <button type="submit" class="form-submit-btn">${submitText}</button>
</form>`.trim();
  }

  private renderToStringStub(): HTMLElement {
    const elem = {
      className: "form-component",
      innerHTML: this.renderToString(),
    } as unknown as HTMLElement;
    return elem;
  }
}

