export interface A11yViolation {
  readonly ruleId: string;
  readonly element: string;
  readonly message: string;
  readonly wcagCriterion: string;
  readonly severity: "error" | "warning";
}

export interface A11yAuditReport {
  readonly passed: boolean;
  readonly score: number;
  readonly violations: readonly A11yViolation[];
  readonly totalRulesChecked: number;
}

export class A11yChecker {
  public static checkDialogAccessibility(html: string): readonly A11yViolation[] {
    const violations: A11yViolation[] = [];

    const hasDialogRole = /role\s*=\s*["']dialog["']|role\s*=\s*["']alertdialog["']/i.test(html);
    if (!hasDialogRole) {
      violations.push({
        ruleId: "dialog-role-missing",
        element: ".modal-dialog",
        message: "Modal dialog container must have role=\"dialog\" or role=\"alertdialog\"",
        wcagCriterion: "4.1.2 Name, Role, Value",
        severity: "error",
      });
    }

    const hasAriaModal = /aria-modal\s*=\s*["']true["']/i.test(html);
    if (!hasAriaModal) {
      violations.push({
        ruleId: "dialog-aria-modal-missing",
        element: ".modal-dialog",
        message: "Modal dialog must specify aria-modal=\"true\"",
        wcagCriterion: "2.4.3 Focus Order",
        severity: "error",
      });
    }

    const hasAccessibleName = /aria-labelledby\s*=|aria-label\s*=/i.test(html);
    if (!hasAccessibleName) {
      violations.push({
        ruleId: "dialog-accessible-name-missing",
        element: ".modal-dialog",
        message: "Modal dialog must specify aria-labelledby or aria-label",
        wcagCriterion: "1.3.1 Info and Relationships",
        severity: "warning",
      });
    }

    return violations;
  }

  public static checkFormAccessibility(html: string): readonly A11yViolation[] {
    const violations: A11yViolation[] = [];

    const labelMatches = html.match(/<label[^>]*>/gi) ?? [];
    for (const labelTag of labelMatches) {
      const hasFor = /for\s*=\s*["'][^"']+["']|htmlFor\s*=\s*["'][^"']+["']/i.test(labelTag);
      if (!hasFor) {
        violations.push({
          ruleId: "form-label-missing-for",
          element: labelTag,
          message: "Form label must specify 'for' or 'htmlFor' attribute linking to control id",
          wcagCriterion: "3.3.2 Labels or Instructions",
          severity: "error",
        });
      }
    }

    const hasLiveRegion = /aria-live\s*=\s*["'](polite|assertive)["']|role\s*=\s*["']alert["']/i.test(html);
    if (!hasLiveRegion) {
      violations.push({
        ruleId: "form-error-missing-live-region",
        element: ".form-error",
        message: "Form error message containers must include aria-live or role=\"alert\"",
        wcagCriterion: "4.1.3 Status Messages",
        severity: "error",
      });
    }

    return violations;
  }

  public static runAudit(htmlContent: string, componentType: "modal" | "form"): A11yAuditReport {
    const violations =
      componentType === "modal"
        ? this.checkDialogAccessibility(htmlContent)
        : this.checkFormAccessibility(htmlContent);

    const errorCount = violations.filter((v) => v.severity === "error").length;
    const totalRules = componentType === "modal" ? 3 : 2;
    const passed = errorCount === 0;
    const score = Math.max(0, Math.round(((totalRules - errorCount) / totalRules) * 100));

    return {
      passed,
      score,
      violations,
      totalRulesChecked: totalRules,
    };
  }
}

